import sys
from collections import defaultdict, deque

def read_input():
    input = sys.stdin.read().split()
    n = int(input[0])
    edges = [(int(input[i * 2 + 1]) - 1, int(input[i * 2 + 2]) - 1) for i in range(n - 1)]
    return n, edges

def find_center(n, edges):
    graph = defaultdict(list)
    degree = [0] * n
    leaves = deque()

    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
        degree[u] += 1
        degree[v] += 1

    for i in range(n):
        if degree[i] == 1:
            leaves.append(i)

    while len(leaves) > 2 or (len(leaves) == 2 and degree[leaves[0]] == 1):
        leaf = leaves.popleft()
        degree[leaf] = 0
        for neighbor in graph[leaf]:
            if degree[neighbor] > 0:
                degree[neighbor] -= 1
                if degree[neighbor] == 1:
                    leaves.append(neighbor)

    return list(leaves)

def dfs(graph, start, visited, component):
    stack = [start]
    while stack:
        node = stack.pop()
        if not visited[node]:
            visited[node] = True
            component.append(node)
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    stack.append(neighbor)

def solve():
    n, edges = read_input()
    centers = find_center(n, edges)
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
    graph[v].append(u)

    visited = [False] * n
    components = []
    for center in centers:
        if not visited[center]:
            component = []
            dfs(graph, center, visited, component)
            components.append(component)

    m = len(components)
    print(m)
    for component in components:
        print(len(component), *(node + 1 for node in component))
    for i in range(1, m):
        print(i, i + 1)

if __name__ == "__main__":
    solve()
